WITH requested(id) AS ( VALUES
(#{id})
) SELECT encode(s.coupon_template_id, 'hex') AS "couponTemplateId", s.scope_target_type AS "scopeTargetType", s.category_id AS "categoryId", s.spu_id AS "spuId", encode(s.sku_id, 'hex') AS "skuId" FROM coupon_scope s INNER JOIN requested r ON r.id = s.coupon_template_id ORDER BY s.created_at ASC
